-- stochastic-processes implementation for DistributionFunctions
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.NormalPDF(x,mean,standardDeviation)
    Num.Positive(standardDeviation,"standard deviation"); local z=(x-mean)/standardDeviation
    return math.exp(-0.5*z*z)/(standardDeviation*math.sqrt(2*math.pi))
end
function Module.ExponentialCDF(x,rate)
    Num.Positive(rate,"rate"); if x<0 then return 0 end; return 1-math.exp(-rate*x)
end

return Module
